<script setup lang="ts">
import {ref,watch,toRaw} from 'vue'
import type {Layer,Transform,EditAction} from '../shared/contracts'
import {transformSchema} from '../shared/transform'
import {blurMaskPixels,maskBackground} from '../shared/mask-pixels'
import {LIMITS} from '../shared/limits'
import type {MaskPreview} from './mask-display'
const props=defineProps<{layer:Layer;url?:string;disabled?:boolean;selected?:boolean;alone?:boolean}>()
const emit=defineEmits<{action:[action:EditAction];select:[];alone:[value:boolean];preview:[preview:MaskPreview|undefined];placement:[placement:Transform|undefined];background:[url:string];error:[message:string]}>()
const draft=ref<Transform>(structuredClone(toRaw(props.layer.maskPlacement??props.layer.transform))),radius=ref(4),filter=ref<'gaussianBlur'|'feather'>('feather'),loading=ref(false)
let source:{width:number;height:number;data:Uint8ClampedArray}|undefined,version=0
function solidURL(value:number):string{const canvas=document.createElement('canvas');canvas.width=canvas.height=1;const context=canvas.getContext('2d')!;context.fillStyle=`rgb(${value},${value},${value})`;context.fillRect(0,0,1,1);return canvas.toDataURL('image/png')}
watch(()=>[props.layer.id,props.url,props.layer.maskPlacement,props.layer.transform],()=>{draft.value=structuredClone(toRaw(props.layer.maskPlacement??props.layer.transform))},{deep:true})
watch(()=>props.url,async url=>{const ticket=++version;source=undefined;emit('preview',undefined);emit('placement',undefined);if(!url)return;loading.value=true;try{const image=new Image();image.src=url;await image.decode();if(ticket!==version)return;if(image.naturalWidth>LIMITS.maxSide||image.naturalHeight>LIMITS.maxSide||image.naturalWidth*image.naturalHeight>LIMITS.maxSurfacePixels)throw Error('Mask exceeds the preview pixel budget.');const canvas=document.createElement('canvas');canvas.width=image.naturalWidth;canvas.height=image.naturalHeight;const context=canvas.getContext('2d',{willReadFrequently:true})!;context.drawImage(image,0,0);source={width:canvas.width,height:canvas.height,data:context.getImageData(0,0,canvas.width,canvas.height).data};emit('background',solidURL(maskBackground(source)))}catch(cause){emit('error',cause instanceof Error?cause.message:String(cause))}finally{if(ticket===version)loading.value=false}},{immediate:true})
function operation(operation:Extract<EditAction,{type:'layer.mask'}>['operation']):void{emit('preview',undefined);emit('placement',undefined);emit('action',{type:'layer.mask',layerId:props.layer.id,operation})}
function previewPlacement():void{const parsed=transformSchema.safeParse(toRaw(draft.value));if(parsed.success)emit('placement',parsed.data)}
function cancelPlacement():void{draft.value=structuredClone(toRaw(props.layer.maskPlacement??props.layer.transform));emit('placement',undefined)}
function place():void{const parsed=transformSchema.safeParse(toRaw(draft.value));if(!parsed.success){emit('error','Enter a valid mask placement.');return}emit('placement',undefined);emit('action',{type:'layer.mask_set_placement',layerId:props.layer.id,transform:parsed.data})}
function preview():void{try{if(!source)throw Error('Wait for the mask raster to load.');const output=blurMaskPixels(source,radius.value),canvas=document.createElement('canvas');canvas.width=output.width;canvas.height=output.height;canvas.getContext('2d')!.putImageData(new ImageData(new Uint8ClampedArray(output.data),output.width,output.height),0,0);emit('preview',{url:canvas.toDataURL('image/png'),width:output.width,height:output.height})}catch(cause){emit('error',cause instanceof Error?cause.message:String(cause))}}
function applyFilter():void{if(!Number.isFinite(radius.value)||radius.value<0||radius.value>250){emit('error','Mask radius must be between 0 and 250 pixels.');return}emit('preview',undefined);emit('action',{type:'layer.mask_filter',layerId:props.layer.id,filter:filter.value,radius:radius.value})}
</script>
<template>
 <section class="mask-panel" aria-label="Raster mask editor"><strong>Raster mask</strong><div class="mask-buttons"><button v-if="!layer.maskFile" :disabled="disabled" @click="operation('reveal')">Reveal all</button><button v-if="!layer.maskFile" :disabled="disabled" @click="operation('hide')">Hide all</button></div>
 <template v-if="layer.maskFile"><div class="mask-buttons"><button :disabled="disabled" @click="emit('select')">{{selected?'Mask selected':'Select mask'}}</button><button @click="emit('alone',!alone)">{{alone?'Show composite':'Show mask alone'}}</button><button :disabled="disabled" @click="operation(layer.maskEnabled===false?'enable':'disable')">{{layer.maskEnabled===false?'Enable':'Disable'}}</button><button :disabled="disabled" @click="operation(layer.maskLinked===false?'link':'unlink')">{{layer.maskLinked===false?'Link':'Unlink'}}</button><button :disabled="disabled" @click="operation('invert')">Invert</button><button :disabled="disabled" @click="operation('remove')">Remove</button><button :disabled="disabled" @click="emit('action',{type:'selection.from_mask',layerId:layer.id,operation:'replace'})">Select hidden pixels</button></div>
 <form novalidate @submit.prevent="place"><fieldset :disabled="disabled"><legend>Independent placement</legend><label>X<input v-model.number="draft.origin[0]" type="number" @input="previewPlacement"></label><label>Y<input v-model.number="draft.origin[1]" type="number" @input="previewPlacement"></label><label>Width<input v-model.number="draft.size[0]" type="number" min="1" @input="previewPlacement"></label><label>Height<input v-model.number="draft.size[1]" type="number" min="1" @input="previewPlacement"></label><label>Rotation<input v-model.number="draft.rotation" type="number" @input="previewPlacement"></label><label><input v-model="draft.flipX" type="checkbox" @change="previewPlacement">Flip horizontal</label><label><input v-model="draft.flipY" type="checkbox" @change="previewPlacement">Flip vertical</label><button type="submit">Apply placement</button><button type="button" @click="cancelPlacement">Cancel placement</button></fieldset></form>
 <fieldset :disabled="disabled||loading"><legend>Mask edges</legend><label>Operation<select v-model="filter"><option value="feather">Feather</option><option value="gaussianBlur">Gaussian blur</option></select></label><label>Radius (pixels)<input v-model.number="radius" type="number" min="0" max="250" step=".1"></label><div class="mask-buttons"><button @click="preview">Preview</button><button @click="applyFilter">Apply</button><button @click="emit('preview',undefined)">Cancel preview</button></div></fieldset><p>Shift-click thumbnail disables the mask. Alt-click shows gray pixels. Ctrl/Cmd-click selects hidden pixels; Shift adds and Alt subtracts.</p></template></section>
</template>
<style scoped>
.mask-panel{border-top:1px solid #444;margin-top:12px;padding-top:10px;font-size:11px}.mask-panel fieldset{border:1px solid #454545;border-radius:5px;padding:8px;margin:10px 0}.mask-panel legend{color:#aaa;padding:0 4px}.mask-panel label{display:flex;align-items:center;justify-content:space-between;margin:7px 0}.mask-panel input,.mask-panel select{width:110px;font-size:11px;padding:4px;background:#202020;color:#ddd;border:1px solid #555;border-radius:4px}.mask-panel input[type=checkbox]{width:auto}.mask-buttons{display:flex;gap:5px;flex-wrap:wrap;margin-top:8px}.mask-panel button{font-size:10px;background:#3a3a3a;border:1px solid #555;border-radius:4px;padding:5px 7px;margin:2px}.mask-panel p{color:#999;line-height:1.6}
</style>
